  ctx.strokeStyle = '#bc9d60'; ctx.lineWidth = 9; ctx.stroke();
  ctx.textAlign = 'center';
  ctx.font = '700 68px Impact, Arial Black, sans-serif';
  ctx.fillStyle = '#b03a42';
