    // Emergency state.
    const emergencyOn = powerOut || mode === 'scare';
    world.lights.emergency.intensity += ((emergencyOn ? 4.5 : 0) - world.lights.emergency.intensity) * Math.min(1, dt * 5);
    world.props.emergencyBulb.material.emissiveIntensity = emergencyOn ? 2.5 + Math.sin(time * 8) * 1.3 : 0;
    world.props.emergencyBulb.material.emissive.set(emergencyOn ? '#ff2212' : '#420b08');

    // Fan and clock.
    world.props.fan.rotation.z += dt * (powerOut ? .4 : 12);
    clockHands[0].rotation.z = -time * .08;
    clockHands[1].rotation.z = -time * .9;

    // Atmosphere.
    world.props.dust.rotation.y = time * .006;
    world.props.dust.position.y = Math.sin(time * .18) * .12;
    world.props.screen.material.emissiveIntensity = .24 + Math.random() * .08;
    world.props.screen.material.emissive.setRGB(.08 + Math.random() * .03, .65, .48);
    world.lights.stageSpot.intensity = 230 + Math.sin(time * 7.3) * 12 + (Math.random() > .985 ? -130 : 0);
    world.props.stageGlow.material.opacity = .34 + Math.sin(time * 1.1) * .05;
    world.lights.cove.intensity = 5 + Math.sin(time * 1.7) * 1.2;

    // Cove curtain opens based on Foxy's progress.
    const cove = world.props.coveCurtain.userData;
    const open = Math.max(0, Math.min(1, foxyProgress / 3));
    cove.left.position.x = -.95 - open * .9;
    cove.right.position.x = .95 + open * .9;
    cove.left.scale.x = 1 - open * .25;
    cove.right.scale.x = 1 - open * .25;

    // Animatronic idle animations.
    for (const [type, char] of Object.entries(world.characters)) {
      const animMode = char.userData.mode || (type === 'foxy' ? 'stage' : 'idle');
      animateAnimatronic(char, time, animMode, char.userData.animationIntensity || 1);
    }
    // Foxy eyes glow from the cove.
    setEyeGlow(world.characters.foxy, .15 + foxyProgress * .3);
    // Security LEDs blink.
    for (const obj of restaurant.children) {
      if (obj.userData?.led) obj.userData.led.material.color.set(Math.sin(time * 3 + obj.position.z) > 0 ? '#ff2a24' : '#3a0907');
    }
  };

  world.setVisibleCharacters = (visibility) => {
    for (const [type, char] of Object.entries(world.characters)) {
      char.visible = visibility[type] !== false;
    }
  };

  world.getCamera = (id) => world.cams[String(id)]?.camera;

  return world;
}

// All audio is synthesized at runtime — no external samples.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.ambient = null;
    this.staticLoop = null;
    this.heartbeatTimer = 0;
    this.musicTimer = 0;
    this.enabled = true;
    this.started = false;
  }

  ensure() {
    if (this.ctx) return this.ctx;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return null;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.62;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoiseBuffer(2.5);
    return this.ctx;
  }

  async unlock() {
    const ctx = this.ensure();
    if (!ctx) return;
    if (ctx.state === 'suspended') await ctx.resume();
    this.started = true;
  }

  makeNoiseBuffer(seconds = 2, brown = false) {
    const ctx = this.ensure();
    const length = Math.floor(ctx.sampleRate * seconds);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      if (brown) {
        last = (last + .02 * white) / 1.02;
        data[i] = last * 3.5;
      } else data[i] = white;
    }
    return buffer;
  }

  noiseSource({ brown = false, loop = true } = {}) {
    const ctx = this.ensure();
    const source = ctx.createBufferSource();
    source.buffer = brown ? this.makeNoiseBuffer(3, true) : this.noiseBuffer;
    source.loop = loop;
    return source;
  }

  tone(freq, duration, { type = 'sine', gain = .08, attack = .005, decay = null, slide = 0, delay = 0, filter = null } = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t0 + duration);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    let node = osc;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = filter.type || 'lowpass';
      f.frequency.value = filter.frequency || 800;
      f.Q.value = filter.q || .7;
      node.connect(f);
      f.connect(g);
    } else node.connect(g);
    g.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + .04);
  }

  noiseBurst(duration = .2, { gain = .12, filter = 900, type = 'lowpass', brown = false, q = 1, delay = 0, sweep = 0 } = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const t0 = ctx.currentTime + delay;
    const source = ctx.createBufferSource();
    source.buffer = brown ? this.makeNoiseBuffer(Math.max(1, duration + .1), true) : this.noiseBuffer;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(filter, t0);
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(30, filter + sweep), t0 + duration);
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + Math.min(.02, duration * .15));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    source.connect(f);
    f.connect(g);
    g.connect(this.master);
    source.start(t0, Math.random() * .2);
    source.stop(t0 + duration + .03);
  }

  startMenu() {
    const ctx = this.ensure();
    if (!ctx || this.ambient) return;
    const source = this.noiseSource({ brown: true });
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 170;
    const gain = ctx.createGain();
    gain.gain.value = .035;
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    source.start();
    const drone = ctx.createOscillator();
    const droneGain = ctx.createGain();
    drone.type = 'sine';
    drone.frequency.value = 43;
    droneGain.gain.value = .018;
    drone.connect(droneGain);
    droneGain.connect(this.master);
    drone.start();
    this.ambient = { source, filter, gain, drone, droneGain };
    // Distant, out-of-tune music box.
    this.musicBox();
  }

  startShift() {
    const ctx = this.ensure();
    if (!ctx) return;
    if (this.ambient) {
      this.ambient.gain.gain.setTargetAtTime(.018, ctx.currentTime, 1.5);
    }
    if (!this.ambient) this.startMenu();
    // Ceiling fan and fluorescent hum.
    const fanSource = this.noiseSource();
    const fanFilter = ctx.createBiquadFilter();
    fanFilter.type = 'lowpass';
    fanFilter.frequency.value = 500;
    const fanGain = ctx.createGain();
    fanGain.gain.value = .018;
    fanSource.connect(fanFilter); fanFilter.connect(fanGain); fanGain.connect(this.master);
    fanSource.start();
    const hum = ctx.createOscillator();
    const humGain = ctx.createGain();
    hum.type = 'sawtooth';
    hum.frequency.value = 120;
    humGain.gain.value = .0035;
    const humFilter = ctx.createBiquadFilter();
    humFilter.type = 'lowpass';
    humFilter.frequency.value = 300;
    hum.connect(humFilter); humFilter.connect(humGain); humGain.connect(this.master);
    hum.start();
    this.fan = { fanSource, fanGain, hum, humGain };
  }

  stopAmbient() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    for (const obj of [this.ambient, this.fan, this.staticLoop]) {
      if (!obj) continue;
      for (const key of ['gain', 'fanGain', 'humGain', 'droneGain']) {
        if (obj[key]) obj[key].gain.setTargetAtTime(0.0001, t, .15);
      }
      setTimeout(() => {
        try {
          obj.source?.stop();
          obj.fanSource?.stop();
          obj.drone?.stop();
          obj.hum?.stop();
        } catch {}
      }, 500);
    }
    this.ambient = null;
    this.fan = null;
    this.staticLoop = null;
  }

  click() {
    this.tone(1100, .035, { type: 'square', gain: .025, filter: { frequency: 1800 } });
  }

  doorClose() {
    this.noiseBurst(.32, { gain: .12, filter: 280, brown: true });
    this.tone(65, .28, { type: 'sawtooth', gain: .09, slide: -28, filter: { frequency: 200 } });
    this.noiseBurst(.06, { gain: .08, filter: 2400, type: 'highpass', delay: .03 });
  }

  doorOpen() {
    this.noiseBurst(.28, { gain: .07, filter: 400, brown: true });
    this.tone(90, .2, { type: 'sawtooth', gain: .035, slide: 45, filter: { frequency: 260 } });
  }

  lightClick(on = true) {
    this.noiseBurst(.03, { gain: .06, filter: 2400, type: 'highpass' });
    if (on) this.tone(210, .12, { type: 'sawtooth', gain: .012, filter: { frequency: 1400 } });
  }

  cameraOn() {
    this.noiseBurst(.45, { gain: .06, filter: 1600, type: 'bandpass', q: 1.4 });
    this.tone(55, .4, { type: 'sine', gain: .035, slide: -15 });
    this.startStatic();
  }

  cameraOff() {
    this.noiseBurst(.12, { gain: .04, filter: 1000 });
    this.stopStatic();
  }

  cameraSwitch() {
    this.noiseBurst(.18, { gain: .06, filter: 2200, type: 'bandpass', q: 2 });
    this.tone(880, .06, { type: 'square', gain: .018 });
  }

  startStatic() {
    const ctx = this.ensure();
    if (!ctx || this.staticLoop) return;
    const source = this.noiseSource();
    const filter = ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 1600;
    const gain = ctx.createGain();
    gain.gain.value = .016;
    source.connect(filter); filter.connect(gain); gain.connect(this.master);
    source.start();
    this.staticLoop = { source, gain, filter };
  }

  stopStatic() {
    if (!this.staticLoop || !this.ctx) return;
    const t = this.ctx.currentTime;
    this.staticLoop.gain.gain.setTargetAtTime(0.0001, t, .12);
    const loop = this.staticLoop;
    this.staticLoop = null;
    setTimeout(() => { try { loop.source.stop(); } catch {} }, 400);
  }

  footstep(pan = 0) {
    const ctx = this.ensure();
    if (!ctx) return;
    const source = this.noiseSource({ brown: true });
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 380;
    const gain = ctx.createGain();
    const panNode = ctx.createStereoPanner();
    panNode.pan.value = Math.max(-1, Math.min(1, pan));
    gain.gain.setValueAtTime(.0001, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(.06, ctx.currentTime + .012);
    gain.gain.exponentialRampToValueAtTime(.0001, ctx.currentTime + .28);
    source.connect(filter); filter.connect(gain); gain.connect(panNode); panNode.connect(this.master);
    source.start();
    source.stop(ctx.currentTime + .32);
  }

  knock(side = 0) {
    const ctx = this.ensure();
    if (!ctx) return;
    const pan = ctx.createStereoPanner();
    pan.pan.value = side;
    pan.connect(this.master);
    for (let i = 0; i < 3; i++) {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(82, ctx.currentTime + i * .15);
      g.gain.setValueAtTime(.0001, ctx.currentTime + i * .15);
      g.gain.exponentialRampToValueAtTime(.09, ctx.currentTime + i * .15 + .006);
      g.gain.exponentialRampToValueAtTime(.0001, ctx.currentTime + i * .15 + .16);
      osc.connect(g); g.connect(pan);
      osc.start(ctx.currentTime + i * .15);
      osc.stop(ctx.currentTime + i * .15 + .18);
    }
  }

  breathing() {
    const ctx = this.ensure();
    if (!ctx) return;
    const source = this.noiseSource({ brown: true });
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 420;
    filter.Q.value = .7;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(.0001, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(.03, ctx.currentTime + .5);
    gain.gain.linearRampToValueAtTime(.0001, ctx.currentTime + 1.3);
    source.connect(filter); filter.connect(gain); gain.connect(this.master);
    source.start();
    source.stop(ctx.currentTime + 1.4);
  }

  foxyRun() {
    this.noiseBurst(.8, { gain: .05, filter: 170, brown: true, sweep: -90 });
    this.tone(94, .45, { type: 'sawtooth', gain: .02, slide: -25, filter: { frequency: 260 } });
    for (let i = 0; i < 4; i++) this.footstep(i % 2 ? .8 : -.8);
  }

  foxyBlocked() {
    this.noiseBurst(.4, { gain: .17, filter: 280, brown: true });
    this.tone(58, .45, { type: 'square', gain: .06, slide: -22, filter: { frequency: 160 } });
  }

  cameraWarning() {
    this.tone(740, .13, { type: 'square', gain: .035 });
    this.tone(740, .13, { type: 'square', gain: .035, delay: .19 });
  }

  powerDown() {
    this.tone(140, 1.8, { type: 'sawtooth', gain: .09, slide: -120, filter: { frequency: 500 } });
    this.noiseBurst(1.3, { gain: .08, filter: 500, brown: true, sweep: -400 });
    this.stopFan();
  }

  stopFan() {
    if (!this.ctx || !this.fan) return;
    this.fan.fanGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, .5);
    this.fan.humGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, .5);
  }

  jumpscare() {
    const ctx = this.ensure();
    if (!ctx) return;
    this.stopStatic();
    const t = ctx.currentTime;
    this.noiseBurst(1.15, { gain: .28, filter: 3200, type: 'highpass' });
    this.noiseBurst(1.0, { gain: .18, filter: 180, brown: true });
    for (const freq of [58, 73, 91, 116, 147]) {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(freq * 2.4, t);
      osc.frequency.exponentialRampToValueAtTime(freq, t + .9);
      g.gain.setValueAtTime(.0001, t);
      g.gain.exponentialRampToValueAtTime(.06 + Math.random() * .03, t + .012);
      g.gain.exponentialRampToValueAtTime(.0001, t + 1.1);
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = 1400;
      osc.connect(f); f.connect(g); g.connect(this.master);
      osc.start(t + Math.random() * .04); osc.stop(t + 1.2);
    }
    // Metal scream.
    for (let i = 0; i < 4; i++) {
      this.tone(1200 + i * 410, .6, { type: 'square', gain: .02, slide: -900, delay: i * .03 });
    }
  }

  chime() {
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) => this.tone(f, 1.2, { type: 'sine', gain: .09, delay: i * .18, attack: .01 }));
    this.tone(261.63, 2, { type: 'triangle', gain: .04, delay: .1 });
  }

  powerOutMusic() {
    if (this.musicTimer) return;
    const melody = [659.25, 587.33, 523.25, 392, 523.25, 659.25, 783.99];
    let step = 0;
    const play = () => {
      if (!this.ctx) return;
      const f = melody[step % melody.length];
      this.tone(f, .34, { type: 'sine', gain: .04, attack: .005 });
      step++;
      if (step < 18) this.musicTimer = setTimeout(play, 420);
      else this.musicTimer = 0;
    };
    play();
  }

  musicBox() {
    // Slow, distant, deliberately imperfect.
    const melody = [523.25, 659.25, 587.33, 392, 440, 523.25, 349.23, 392];
    let step = 0;
    const play = () => {
      if (!this.ctx) return;
      if (!this.ambient) return;
      const f = melody[step % melody.length] * (0.997 + Math.random() * .006);
      this.tone(f, 1.0, { type: 'triangle', gain: .014, attack: .008 });
      step++;
      this.musicTimer = setTimeout(play, 850);
    };
    setTimeout(play, 2000);
  }

  stopMusic() {
    if (this.musicTimer) clearTimeout(this.musicTimer);
    this.musicTimer = 0;
  }

  heartbeat(rate = 1) {
    if (!this.ctx) return;
    const now = performance.now();
    if (now - this.heartbeatTimer < 700 / rate) return;
    this.heartbeatTimer = now;
    this.tone(56, .14, { type: 'sine', gain: .07, slide: -18 });
    this.tone(48, .18, { type: 'sine', gain: .055, slide: -12, delay: .17 });
  }

  staticCrackle() {
    this.noiseBurst(.06, { gain: .02, filter: 3400, type: 'highpass' });
  }
}

@import '@fontsource/bebas-neue/400.css';
@import '@fontsource/special-elite/400.css';

:root {
  --ink: #080706;
  --cream: #e7ddc3;
  --cream-dim: #a89f88;
  --red: #bd2e2f;
  --red-bright: #ff3b2d;
  --amber: #e0a83f;
  --green: #73d6a0;
  --green-dim: #2c7254;
  --panel: rgba(11, 10, 9, .88);
  --line: rgba(231, 221, 195, .2);
  --bebas: 'Bebas Neue', Impact, 'Arial Narrow', sans-serif;
  --type: 'Special Elite', 'Courier New', monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --noise: none;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: var(--ink); }
body {
  font-family: var(--bebas);
  color: var(--cream);
  user-select: none;
  -webkit-user-select: none;
  overscroll-behavior: none;
  touch-action: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--amber); outline-offset: 3px; }
.hidden { display: none !important; }

#app, #game-shell, #game-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
}
#app { background: #050404; }
#game-shell { z-index: 0; }
#game-canvas {
  display: block;
  touch-action: none;
  transition: filter .32s ease, transform .2s ease;
  background: #050404;
}
body.camera-open #game-canvas {
  filter: saturate(.58) contrast(1.16) brightness(.86) sepia(.18);
}
body.scare #game-canvas { animation: camShake .08s steps(2) infinite; }

.screen-fx { position: fixed; inset: 0; z-index: 2; pointer-events: none; }
.vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 44%, transparent 20%, rgba(0,0,0,.22) 60%, rgba(0,0,0,.8) 100%),
    linear-gradient(180deg, rgba(0,0,0,.25), transparent 22%, transparent 78%, rgba(0,0,0,.35));
}
.grain {
  position: absolute; inset: -30%;
  background-image: var(--noise);
  background-size: 180px 180px;
  opacity: .07;
  animation: grainShift .23s steps(3) infinite;
  mix-blend-mode: screen;
}
.letterbox {
  position: absolute; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, transparent, rgba(231,221,195,.16), transparent);
}
.letterbox.top { top: calc(var(--safe-top) + 4px); }
.letterbox.bottom { bottom: calc(var(--safe-bottom) + 4px); }

@keyframes grainShift {
  0% { transform: translate3d(-2%, 1%, 0); }
  33% { transform: translate3d(2%, -3%, 0); }
  66% { transform: translate3d(-1%, 3%, 0); }
  100% { transform: translate3d(3%, -1%, 0); }
}
@keyframes camShake {
  0% { transform: translate(0, 0) scale(1.01); }
  25% { transform: translate(4px, -3px) scale(1.02); }
  50% { transform: translate(-5px, 2px) scale(1.01); }
  75% { transform: translate(2px, 4px) scale(1.025); }
  100% { transform: translate(-2px, -2px) scale(1.01); }
}

/* ------------------------------------------------------------------ BOOT */
.boot-screen {
  position: fixed; inset: 0; z-index: 100;
  display: grid; place-content: center; justify-items: center;
  gap: 28px; background: #060505;
  transition: opacity .8s ease;
}
.boot-screen.gone { opacity: 0; pointer-events: none; }
.boot-mark { font-size: 13px; letter-spacing: .34em; color: var(--cream-dim); display: flex; align-items: center; gap: 12px; }
.boot-star { color: var(--amber); font-size: 20px; }
.boot-loader { width: 180px; height: 2px; background: rgba(255,255,255,.1); overflow: hidden; }
.boot-loader i { display: block; height: 100%; width: 45%; background: var(--amber); animation: bootSlide 1.2s ease-in-out infinite; }
@keyframes bootSlide { 0% { transform: translateX(-110%); } 100% { transform: translateX(340%); } }
.boot-copy { font-family: var(--type); font-size: 10px; letter-spacing: .22em; color: #6d665a; }

/* ------------------------------------------------------------------ MENU */
.menu {
  position: fixed; inset: 0; z-index: 10;
  display: flex; flex-direction: column;
  padding: calc(var(--safe-top) + 20px) calc(var(--safe-right) + 24px) calc(var(--safe-bottom) + 18px) calc(var(--safe-left) + 24px);
  background:
    linear-gradient(180deg, rgba(4,3,3,.76) 0%, rgba(4,3,3,.06) 35%, rgba(4,3,3,.38) 60%, rgba(4,3,3,.94) 100%),
    radial-gradient(ellipse at 50% 38%, transparent 0, rgba(0,0,0,.28) 62%, rgba(0,0,0,.7) 100%);
}
.menu::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,.02) 0 1px, transparent 1px 4px);
  opacity: .35;
}
.menu-shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(0,0,0,.3), transparent 24%, transparent 76%, rgba(0,0,0,.3)); pointer-events: none; }
.menu-top { display: flex; justify-content: space-between; align-items: center; position: relative; z-index: 2; }
.est { font-family: var(--type); font-size: 9px; letter-spacing: .2em; color: rgba(231,221,195,.55); }
.est span { margin: 0 7px; color: var(--red); }
.icon-btn {
  width: 42px; height: 42px; border: 1px solid rgba(231,221,195,.25);
  border-radius: 50%; font-size: 18px; color: var(--cream-dim);
  background: rgba(8,7,6,.4); backdrop-filter: blur(8px);
  display: grid; place-items: center; transition: .2s;
}
.icon-btn:hover { border-color: var(--amber); color: var(--amber); transform: rotate(20deg); }

.title-lockup {
  position: relative; z-index: 2;
  margin-top: clamp(28px, 7vh, 78px);
  text-align: center;
  filter: drop-shadow(0 10px 40px rgba(0,0,0,.8));
}
.title-kicker {
  margin: 0 0 -4px;
  font-size: clamp(14px, 3.5vw, 23px);
  letter-spacing: .56em; color: var(--cream); opacity: .84;
  text-shadow: 0 2px 16px #000;
}
.title-lockup h1 { margin: 0; line-height: .78; }
.title-freddy {
  display: inline-block;
  font-family: var(--bebas);
  font-size: clamp(82px, 24vw, 190px);
  letter-spacing: .012em;
  color: #e8dcc0;
  background: linear-gradient(180deg, #f5ead0 0%, #d6c39c 45%, #8f7d5e 79%, #c4ae83 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 0 rgba(40,25,14,.2);
  position: relative;
}
.title-freddy::before {
  content: attr(data-text);
  position: absolute; inset: 0; z-index: -1;
  color: transparent; -webkit-text-stroke: 2px rgba(15,9,5,.55);
  transform: translate(4px, 7px);
}
.title-rule {
  display: flex; align-items: center; justify-content: center; gap: 12px;
  margin: 2px auto 0; max-width: 540px;
  color: var(--red-bright);
}
.title-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, currentColor); opacity: .45; }
.title-rule span:last-child { background: linear-gradient(90deg, currentColor, transparent); }
.title-rule b { font-size: clamp(14px, 3vw, 21px); letter-spacing: .42em; font-weight: 400; }
.title-sub { margin: 9px 0 0; font-family: var(--type); font-size: clamp(7px, 1.7vw, 10px); letter-spacing: .3em; color: rgba(231,221,195,.42); }

.menu-bottom { position: relative; z-index: 2; margin-top: auto; display: flex; flex-direction: column; align-items: center; gap: 12px; }
.night-chip {
  display: grid; grid-template-columns: auto auto; align-items: center;
  column-gap: 12px; row-gap: 0;
  padding: 8px 18px; border: 1px solid rgba(231,221,195,.18);
  background: rgba(8,7,6,.48); backdrop-filter: blur(10px);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.chip-label { grid-column: 1; font-size: 8px; letter-spacing: .24em; color: var(--cream-dim); align-self: end; }
.night-chip strong { grid-column: 1; grid-row: 2; font-size: 26px; letter-spacing: .1em; line-height: 1; color: var(--amber); font-weight: 400; }
.chip-sub { grid-column: 2; grid-row: 1 / span 2; font-family: var(--type); font-size: 8px; letter-spacing: .1em; color: rgba(231,221,195,.5); border-left: 1px solid rgba(231,221,195,.16); padding-left: 12px; }

.menu-actions { width: min(390px, 92vw); display: flex; flex-direction: column; gap: 8px; }
.start-btn {
  position: relative; display: grid; grid-template-columns: 1fr auto; align-items: center;
  width: 100%; height: 65px; padding: 0 28px; text-align: left;
  background: linear-gradient(100deg, #9d272a 0%, #7a1b1e 55%, #521214 100%);
  border: 1px solid rgba(255,143,122,.3);
  box-shadow: 0 10px 35px rgba(132,24,27,.3), inset 0 1px 0 rgba(255,255,255,.12);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  transition: transform .18s ease, filter .18s ease;
  overflow: hidden;
}
.start-btn::before {
  content: ''; position: absolute; inset: 0;
  background: repeating-linear-gradient(105deg, transparent 0 20px, rgba(255,255,255,.035) 20px 21px);
}
.start-btn:hover { transform: translateY(-2px); filter: brightness(1.16); }
.start-btn:active { transform: scale(.985); }
.start-label { grid-row: 1; font-size: 36px; letter-spacing: .16em; line-height: .9; }
.start-sub { grid-row: 2; font-family: var(--type); font-size: 7px; letter-spacing: .22em; color: rgba(244,226,202,.62); margin-top: 3px; }
.start-arrow { grid-column: 2; grid-row: 1 / span 2; font-size: 45px; line-height: 1; color: rgba(255,228,198,.72); }
.menu-secondary { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ghost-btn {
  height: 42px; border: 1px solid rgba(231,221,195,.2);
  background: rgba(11,10,9,.55); color: var(--cream-dim);
  font-size: 13px; letter-spacing: .22em; backdrop-filter: blur(8px);
  transition: .18s;
}
.ghost-btn:hover { border-color: rgba(231,221,195,.6); color: var(--cream); background: rgba(231,221,195,.06); }
.ghost-btn.small { height: 32px; padding: 0 16px; font-size: 11px; }
.headphones { margin: 2px 0 0; font-family: var(--type); font-size: 7px; letter-spacing: .18em; color: rgba(231,221,195,.33); }
.headphones span { margin: 0 5px; }
.menu-footer {
  position: relative; z-index: 2; text-align: center;
  margin-top: 14px; font-family: var(--type); font-size: 6px;
  letter-spacing: .16em; color: rgba(231,221,195,.2);
}

/* ------------------------------------------------------------------ HUD */
.hud { position: fixed; inset: 0; z-index: 8; pointer-events: none; padding: calc(var(--safe-top) + 12px) calc(var(--safe-right) + 14px) calc(var(--safe-bottom) + 14px) calc(var(--safe-left) + 14px); }
.hud-grain { position: absolute; inset: 0; background-image: var(--noise); opacity: .04; pointer-events: none; mix-blend-mode: screen; }
.hud-top {
  display: grid; grid-template-columns: 1fr auto 1.2fr; align-items: start; gap: 10px;
  max-width: 980px; margin: 0 auto;
}
.shift-box { display: flex; flex-direction: column; gap: 1px; padding-left: 3px; }
.hud-eyebrow { font-family: var(--type); font-size: 7px; letter-spacing: .2em; color: rgba(231,221,195,.44); }
.shift-box strong { font-size: 17px; letter-spacing: .12em; font-weight: 400; line-height: 1; }
.shift-box span:last-child { font-family: var(--type); font-size: 8px; letter-spacing: .12em; color: var(--amber); margin-top: 3px; }
.clock-box { text-align: center; display: flex; align-items: baseline; gap: 4px; position: relative; padding-bottom: 9px; }
#clock { font-size: clamp(32px, 7vw, 46px); line-height: .7; letter-spacing: .06em; text-shadow: 0 0 22px rgba(255,214,153,.14); }
.clock-am { font-size: 14px; letter-spacing: .12em; color: rgba(231,221,195,.55); }
.clock-progress { position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 68px; height: 2px; background: rgba(255,255,255,.12); }
.clock-progress i { display: block; width: 0%; height: 100%; background: var(--amber); box-shadow: 0 0 8px var(--amber); }
.power-box { justify-self: end; width: min(155px, 38vw); }
.power-line { display: flex; justify-content: space-between; align-items: baseline; }
.power-line strong { font-size: 18px; letter-spacing: .04em; font-weight: 400; color: var(--green); }
.power-bar { height: 6px; background: rgba(255,255,255,.1); margin-top: 3px; overflow: hidden; border-radius: 1px; }
.power-bar i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #397c59, #7ce0a5); transition: width .15s linear, background .2s; box-shadow: 0 0 8px rgba(100,220,160,.45); }
.power-box.warn .power-line strong { color: var(--amber); }
.power-box.warn .power-bar i { background: linear-gradient(90deg, #8f671e, #e0a83f); }
.power-box.danger .power-line strong { color: var(--red-bright); animation: blink .7s steps(2) infinite; }
.power-box.danger .power-bar i { background: linear-gradient(90deg, #7f1c1d, #f14035); }
@keyframes blink { 50% { opacity: .35; } }
.usage-line { display: flex; align-items: center; justify-content: flex-end; gap: 6px; margin-top: 3px; }
.usage-line span { font-family: var(--type); font-size: 6px; letter-spacing: .18em; color: rgba(231,221,195,.38); }
.usage-bars { display: flex; gap: 2px; }
.usage-bars i { width: 9px; height: 4px; background: rgba(255,255,255,.12); }
.usage-bars i.on { background: var(--green); box-shadow: 0 0 5px rgba(100,220,160,.5); }
.usage-bars i.hot { background: var(--amber); box-shadow: 0 0 5px rgba(224,168,63,.5); }

.look-zone { position: absolute; inset: 70px 0 160px; pointer-events: none; display: flex; align-items: center; justify-content: center; }
.look-hint {
  display: flex; gap: 9px; align-items: center; padding: 8px 14px;
  font-family: var(--type); font-size: 7px; letter-spacing: .2em;
  color: rgba(231,221,195,.55); background: rgba(6,5,4,.42);
  border: 1px solid rgba(231,221,195,.12); backdrop-filter: blur(4px);
  transition: opacity .5s, transform .5s;
}
.look-hint span { font-size: 14px; color: var(--amber); }
.look-hint.hide { opacity: 0; transform: translateY(8px); }

.control-cluster { position: absolute; bottom: calc(var(--safe-bottom) + 18px); display: flex; flex-direction: column; gap: 7px; pointer-events: auto; }
.controls-left { left: calc(var(--safe-left) + 16px); }
.controls-right { right: calc(var(--safe-right) + 16px); }
.control {
  position: relative; width: 74px; height: 55px;
  border: 1px solid rgba(231,221,195,.25);
  background: linear-gradient(145deg, rgba(25,23,20,.92), rgba(8,7,6,.88));
  backdrop-filter: blur(10px);
  display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
  padding: 0 10px; text-align: left; gap: 2px;
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 0 100%);
  transition: background .15s, border-color .15s, transform .1s;
}
.control:active { transform: scale(.95); }
.control-key { font-size: 16px; letter-spacing: .09em; line-height: 1; color: var(--cream); }
.control-label { font-family: var(--type); font-size: 6px; letter-spacing: .18em; color: rgba(231,221,195,.42); }
.control-dot { position: absolute; right: 9px; top: 9px; width: 4px; height: 4px; border-radius: 50%; background: rgba(255,255,255,.16); }
.control.active { border-color: rgba(255,71,54,.8); background: linear-gradient(145deg, rgba(100,22,21,.92), rgba(33,9,8,.9)); box-shadow: 0 0 22px rgba(190,40,38,.18); }
.control.active .control-dot { background: var(--red-bright); box-shadow: 0 0 8px var(--red-bright); }
.light-control { height: 49px; }
.light-control.active { border-color: rgba(255,204,118,.75); background: linear-gradient(145deg, rgba(95,70,22,.55), rgba(30,22,9,.9)); box-shadow: 0 0 22px rgba(228,171,67,.14); }
.light-control.active .control-dot { background: var(--amber); box-shadow: 0 0 8px var(--amber); }

.camera-btn {
  position: absolute; left: 50%; transform: translateX(-50%);
  bottom: calc(var(--safe-bottom) + 18px); width: 86px; height: 78px;
  pointer-events: auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px;
  border: 1px solid rgba(231,221,195,.26); background: linear-gradient(160deg, rgba(28,26,22,.94), rgba(7,7,6,.94));
  clip-path: polygon(9px 0, calc(100% - 9px) 0, 100% 9px, 100% calc(100% - 9px), calc(100% - 9px) 100%, 9px 100%, 0 calc(100% - 9px), 0 9px);
  backdrop-filter: blur(12px); font-size: 9px; letter-spacing: .18em; color: var(--cream-dim);
  transition: .18s;
}
.camera-btn:hover, .camera-btn:active { border-color: var(--amber); color: var(--cream); background: linear-gradient(160deg, rgba(59,48,28,.95), rgba(15,12,8,.95)); }
.camera-icon { position: relative; width: 28px; height: 19px; border: 2px solid currentColor; border-radius: 2px; }
.camera-icon::after { content: ''; position: absolute; right: -8px; top: 4px; border-left: 7px solid currentColor; border-top: 4px solid transparent; border-bottom: 4px solid transparent; }
.camera-icon i { position: absolute; right: 4px; top: 4px; width: 4px; height: 4px; border-radius: 50%; background: var(--red-bright); box-shadow: 0 0 5px var(--red-bright); }
.camera-btn kbd { position: absolute; right: 4px; bottom: 2px; font-family: var(--type); font-size: 6px; color: rgba(231,221,195,.27); }

.threat-hint { font-family: var(--type); font-size: 7px; letter-spacing: .18em; color: rgba(231,221,195,.34); transition: color .2s; }
.threat-hint.danger { color: var(--red-bright); animation: blink .55s steps(2) infinite; }
.threat-hint.warn { color: var(--amber); }
.hud-bottom {
  position: absolute; bottom: calc(var(--safe-bottom) + 4px); left: 50%; transform: translateX(-50%);
  width: max-content; max-width: 72vw; display: flex; align-items: center; gap: 15px;
}
.hud-tip { font-family: var(--type); font-size: 5px; letter-spacing: .2em; color: rgba(231,221,195,.18); }

.toast {
  position: absolute; left: 50%; bottom: calc(var(--safe-bottom) + 115px); transform: translate(-50%, 12px);
  max-width: min(360px, 82vw); padding: 9px 16px;
  border: 1px solid rgba(231,221,195,.16); border-left: 3px solid var(--amber);
  background: rgba(8,7,6,.86); backdrop-filter: blur(10px);
  font-family: var(--type); font-size: 9px; line-height: 1.5; letter-spacing: .06em;
  color: rgba(231,221,195,.82); text-align: center;
  opacity: 0; pointer-events: none; transition: opacity .22s, transform .22s;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.danger { border-left-color: var(--red-bright); color: #ffd6cd; }

.edge-indicator {
  position: absolute; top: 38%; display: flex; flex-direction: column; align-items: center; gap: 3px;
  opacity: 0; transition: opacity .2s;
}
.edge-indicator.left { left: 5px; }
.edge-indicator.right { right: 5px; }
.edge-indicator span {
  width: 24px; height: 24px; display: grid; place-items: center;
  border: 1px solid var(--red-bright); border-radius: 50%; color: var(--red-bright);
  font-size: 17px; background: rgba(70,8,8,.4); animation: blink .65s steps(2) infinite;
}
.edge-indicator em { font-style: normal; font-family: var(--type); font-size: 6px; letter-spacing: .2em; color: rgba(255,120,100,.65); }
.edge-indicator.show { opacity: 1; }

.door-alert {
  position: fixed; left: 50%; top: 22%; transform: translate(-50%, -50%);
  display: none; place-items: center; pointer-events: none;
}
.door-alert.show { display: grid; }
.door-alert b { font-size: 60px; color: var(--red-bright); text-shadow: 0 0 24px rgba(255,44,28,.6); position: relative; z-index: 2; }
.pulse-ring { position: absolute; width: 60px; height: 60px; border: 1px solid rgba(255,60,40,.7); border-radius: 50%; animation: ring 1.3s ease-out infinite; }
@keyframes ring { 0% { transform: scale(.6); opacity: .8; } 100% { transform: scale(2.6); opacity: 0; } }

/* ------------------------------------------------------------------ TABLET */
.tablet {
  position: fixed; inset: 0; z-index: 20;
  display: flex; flex-direction: column;
  padding: calc(var(--safe-top) + 8px) calc(var(--safe-right) + 8px) calc(var(--safe-bottom) + 8px) calc(var(--safe-left) + 8px);
  background: radial-gradient(ellipse at 50% 45%, rgba(2,6,4,.1), rgba(1,3,2,.72) 85%);
  animation: tabletIn .3s ease-out;
}
@keyframes tabletIn { from { opacity: 0; transform: scale(1.03); } to { opacity: 1; transform: scale(1); } }
.tablet-chrome {
  position: relative; flex: 1; display: flex; flex-direction: column;
  max-width: 1100px; width: 100%; margin: 0 auto;
  border: 1px solid rgba(128,220,172,.26);
  background: rgba(2,7,4,.36);
  box-shadow: 0 0 80px rgba(0,0,0,.8), inset 0 0 80px rgba(35,120,78,.05);
  overflow: hidden;
}
.tablet-chrome::before {
  content: ''; position: absolute; inset: 0; pointer-events: none; z-index: 5;
  background: linear-gradient(90deg, rgba(0,0,0,.35), transparent 8%, transparent 92%, rgba(0,0,0,.35));
}
.tablet-top {
  position: relative; z-index: 8;
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center;
  min-height: 48px; padding: 6px 12px;
  background: linear-gradient(180deg, rgba(9,15,11,.97), rgba(3,6,4,.92));
  border-bottom: 1px solid rgba(126,214,167,.2);
}
.tablet-brand { display: flex; align-items: center; gap: 8px; }
.fazbear-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); }
.tablet-brand strong { display: block; font-size: 13px; letter-spacing: .2em; color: #a9ebc7; line-height: 1; }
.tablet-brand small { display: block; font-family: var(--type); font-size: 5px; letter-spacing: .18em; color: rgba(160,220,186,.45); margin-top: 2px; }
.cam-title { text-align: center; }
.cam-title span { display: block; font-size: 16px; letter-spacing: .24em; color: #b4f4cf; line-height: 1; }
.cam-title strong { display: block; font-family: var(--type); font-size: 7px; letter-spacing: .18em; color: rgba(184,237,207,.55); margin-top: 3px; font-weight: 400; }
.tablet-exit {
  justify-self: end; display: flex; align-items: center; gap: 6px;
  height: 30px; padding: 0 10px; border: 1px solid rgba(158,229,190,.28);
  font-size: 11px; letter-spacing: .16em; color: #b6ebcd; background: rgba(33,83,56,.16);
}
.tablet-exit span { font-size: 13px; color: #ff6658; }
.cam-viewport {
  position: relative; flex: 1; min-height: 100px; overflow: hidden;
  background:
    repeating-linear-gradient(0deg, rgba(118,255,184,.025) 0 1px, transparent 1px 4px),
    radial-gradient(ellipse at center, rgba(40,100,70,.12), rgba(0,0,0,.68));
}
.cam-viewport::after {
  content: ''; position: absolute; inset: 0; pointer-events: none; z-index: 2;
  box-shadow: inset 0 0 70px rgba(0,0,0,.85), inset 0 0 14px rgba(92,255,162,.09);
}
.camera-overlay { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
.cam-corners i { position: absolute; width: 24px; height: 24px; border-color: rgba(151,255,197,.55); border-style: solid; }
.cam-corners i:nth-child(1) { left: 14px; top: 14px; border-width: 1px 0 0 1px; }
.cam-corners i:nth-child(2) { right: 14px; top: 14px; border-width: 1px 1px 0 0; }
.cam-corners i:nth-child(3) { left: 14px; bottom: 14px; border-width: 0 0 1px 1px; }
.cam-corners i:nth-child(4) { right: 14px; bottom: 14px; border-width: 0 1px 1px 0; }
.cam-rec { position: absolute; left: 26px; top: 25px; display: flex; align-items: center; gap: 6px; font-family: var(--type); font-size: 8px; letter-spacing: .18em; color: rgba(196,255,219,.7); }
.cam-rec span { width: 6px; height: 6px; border-radius: 50%; background: #ff3c2f; box-shadow: 0 0 8px #ff3c2f; animation: blink 1.3s steps(2) infinite; }
.cam-time { position: absolute; right: 26px; top: 25px; font-family: var(--type); font-size: 8px; letter-spacing: .14em; color: rgba(196,255,219,.6); }
.cam-channel { position: absolute; left: 26px; bottom: 25px; font-family: var(--type); font-size: 8px; letter-spacing: .16em; color: rgba(196,255,219,.45); }
.scanlines { position: absolute; inset: 0; background: repeating-linear-gradient(0deg, rgba(118,255,184,.045) 0 1px, transparent 1px 3px); mix-blend-mode: screen; }
.cam-noise { position: absolute; inset: -20%; background-image: var(--noise); background-size: 140px; opacity: .12; animation: grainShift .19s steps(3) infinite; mix-blend-mode: screen; }
.cam-flicker { position: absolute; inset: 0; background: rgba(168,255,210,.025); animation: flicker 3.7s steps(1) infinite; }
@keyframes flicker { 0%, 100% { opacity: .2; } 7% { opacity: .75; } 8% { opacity: .2; } 43% { opacity: .1; } 44% { opacity: .6; } 45% { opacity: .18; } 72% { opacity: .5; } 73% { opacity: .15; } }
.cam-warning {
  position: absolute; left: 50%; bottom: 48px; transform: translateX(-50%);
  font-family: var(--type); font-size: 7px; letter-spacing: .18em; color: rgba(255,111,92,.7);
  opacity: 0; transition: opacity .2s; z-index: 4;
}
.cam-warning.show { opacity: 1; animation: blink .8s steps(2) infinite; }
.tablet-foot {
  position: relative; z-index: 8; padding: 8px 12px calc(10px + var(--safe-bottom));
  background: linear-gradient(0deg, rgba(7,12,8,.98), rgba(4,8,5,.92));
  border-top: 1px solid rgba(126,214,167,.2);
}
.power-mini { display: flex; align-items: center; gap: 8px; margin-bottom: 7px; }
.power-mini span { font-family: var(--type); font-size: 6px; letter-spacing: .18em; color: rgba(171,231,196,.45); }
.power-mini strong { font-size: 14px; color: #7be2a9; font-weight: 400; letter-spacing: .04em; }
.mini-bar { flex: 1; max-width: 190px; height: 3px; background: rgba(255,255,255,.1); }
.mini-bar i { display: block; width: 100%; height: 100%; background: #69d99a; transition: width .15s linear; }
.cam-map { display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px; }
.cam-map-btn {
  min-height: 43px; padding: 4px 3px; border: 1px solid rgba(138,224,176,.2);
  background: rgba(19,41,28,.35); color: rgba(181,233,204,.64);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  transition: .16s;
}
.cam-map-btn b { font-size: 14px; font-weight: 400; letter-spacing: .08em; line-height: 1; }
.cam-map-btn span { font-family: var(--type); font-size: 4.5px; letter-spacing: .07em; white-space: nowrap; }
.cam-map-btn.active { border-color: rgba(127,255,180,.75); color: #c9ffe0; background: rgba(46,119,76,.5); box-shadow: 0 0 14px rgba(80,230,145,.12); }
.cam-map-btn:hover { border-color: rgba(147,240,189,.55); color: #d6ffe8; }
.tablet-hint { text-align: center; margin-top: 6px; font-family: var(--type); font-size: 5px; letter-spacing: .14em; color: rgba(166,226,191,.3); }

/* ------------------------------------------------------------------ BRIEFING */
.briefing {
  position: fixed; inset: 0; z-index: 30; display: grid; place-items: center;
  background: radial-gradient(ellipse at center, rgba(21,17,13,.94), rgba(3,3,3,.985));
  animation: fadeIn .4s ease;
}
.briefing.out { animation: fadeOut .7s ease forwards; }
