.briefing-inner { text-align: center; padding: 20px; max-width: 520px; }
.brief-kicker { font-family: var(--type); font-size: 8px; letter-spacing: .36em; color: rgba(231,221,195,.4); margin: 0 0 18px; }
.briefing h2 { font-size: clamp(66px, 19vw, 128px); letter-spacing: .09em; line-height: .8; margin: 0; color: var(--cream); text-shadow: 0 6px 40px rgba(0,0,0,.8); }
.brief-line { width: 70px; height: 1px; background: var(--red); margin: 23px auto; box-shadow: 0 0 12px var(--red); }
.brief-time { font-family: var(--type); font-size: 16px; letter-spacing: .28em; color: var(--amber); margin: 0 0 16px; }
.brief-copy { font-family: var(--type); font-size: 11px; line-height: 1.8; letter-spacing: .04em; color: rgba(231,221,195,.7); max-width: 380px; margin: 0 auto 24px; }
.brief-tip { display: inline-block; padding: 9px 15px; border: 1px solid rgba(231,221,195,.15); font-family: var(--type); font-size: 7px; letter-spacing: .08em; color: rgba(231,221,195,.45); }

/* ------------------------------------------------------------------ FOXY / POWER OUT */
.foxy-warning {
  position: fixed; left: 0; right: 0; top: 33%; z-index: 18;
  pointer-events: none; display: flex; flex-direction: column; align-items: center;
  opacity: 0; transform: scale(.92);
  transition: opacity .12s, transform .12s;
}
.foxy-warning.show { opacity: 1; transform: scale(1); animation: warningPulse .55s steps(2) infinite; }
.foxy-warning span {
  font-size: clamp(90px, 30vw, 230px); line-height: .8; color: #ff3528;
  text-shadow: 0 0 20px rgba(255,31,18,.7), 0 0 80px rgba(255,31,18,.35);
  letter-spacing: .1em;
}
.foxy-warning small { margin-top: 12px; font-family: var(--type); font-size: 8px; letter-spacing: .24em; color: #ffc1b4; background: rgba(62,5,3,.65); padding: 7px 14px; border: 1px solid rgba(255,65,48,.4); }
