.power-out-copy small { display: block; margin-top: 12px; font-family: var(--type); font-size: 9px; letter-spacing: .22em; color: rgba(255,70,52,.62); animation: blink 1.4s steps(2) infinite; }
.power-out-eyes { position: absolute; left: 50%; top: 48%; transform: translate(-50%, -50%); display: flex; gap: 42px; opacity: 0; }
.power-out.show .power-out-eyes { animation: eyesAppear 1s 2.2s forwards; }
.power-out-eyes i { width: 12px; height: 7px; border-radius: 50%; background: #fff2c6; box-shadow: 0 0 16px 5px rgba(255,230,150,.8), 0 0 60px 20px rgba(255,120,30,.2); }
@keyframes eyesAppear { to { opacity: 1; } }

/* ------------------------------------------------------------------ JUMPSCARE */
.scare-fx {
  position: fixed; inset: 0; z-index: 50; pointer-events: none; display: none;
  background: radial-gradient(ellipse at center, transparent 25%, rgba(124,7,0,.35) 65%, rgba(39,0,0,.92) 100%);
}
.scare-fx.show { display: block; animation: scareFlash .09s steps(2) infinite; }
.scare-static { position: absolute; inset: -30%; background-image: var(--noise); background-size: 130px; opacity: .34; mix-blend-mode: screen; animation: grainShift .11s steps(2) infinite; }
.scare-title { position: absolute; bottom: 7%; left: 50%; transform: translateX(-50%); font-family: var(--type); font-size: 9px; letter-spacing: .4em; color: rgba(255,230,215,.8); text-shadow: 0 0 20px #ff3a20; }
@keyframes scareFlash { 0% { background-color: rgba(255,37,18,.16); } 50% { background-color: rgba(0,0,0,.1); } 100% { background-color: rgba(255,37,18,.08); } }

/* ------------------------------------------------------------------ END SCREENS */
.end-screen {
