.end-inner { position: relative; z-index: 2; text-align: center; width: min(460px, 100%); }
.end-kicker { font-family: var(--type); font-size: 8px; letter-spacing: .3em; color: rgba(255,118,102,.6); margin: 0 0 15px; }
