.end-stat strong { font-size: 22px; font-weight: 400; letter-spacing: .04em; color: var(--cream); }
.end-actions { display: grid; grid-template-columns: 1.3fr 1fr; gap: 8px; width: min(360px, 90%); margin: 0 auto; }
.primary-btn {
