startNight(n) {
  const night = clamp(Number(n) || 1, 1, Math.max(1, this.save.unlocked));
  this.night = night;
  this.cfg = NIGHT_CONFIGS[night - 1];
  this.state = 'briefing';
  this.power = 100;
  this.elapsed = 0;
  this.powerOut = false;
  this.blackoutTimer = 0;
  this.doors = { left: false, right: false };
