import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';
const exe = '/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome';
const browser = await chromium.launch({ executablePath: exe, headless: true, args: ['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 620 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const forcePlaying = () => page.evaluate(() => {
  const g = window.__FNAF.game;
  g.state='playing'; g.briefingTimer=3.4;
  document.querySelector('#briefing').classList.add('hidden');
  document.querySelector('#hud').classList.remove('hidden');
});
await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
await page.waitForTimeout(1200);

// Settings interactions
await page.click('#settingsBtn');
await page.waitForTimeout(400);
await page.click('#qualityControl button[data-quality="performance"]');
await page.click('#hapticsToggle');
const settings = await page.evaluate(() => ({ quality: window.__FNAF.game.save.quality, haptics: window.__FNAF.game.save.haptics, open: !document.querySelector('#settingsModal').classList.contains('hidden') }));
await page.click('[data-close="settingsModal"]');

// How-to
await page.click('#howBtn');
await page.waitForTimeout(300);
const howOpen = await page.evaluate(() => !document.querySelector('#howModal').classList.contains('hidden'));
await page.click('[data-close="howModal"]');

// Night select + play
await page.click('#nightsBtn');
await page.waitForTimeout(300);
const nightOpen = await page.evaluate(() => ({ open: !document.querySelector('#nightSelect').classList.contains('hidden'), cards: document.querySelectorAll('.night-btn').length, playLabel: document.querySelector('#nightPlayBtn').textContent }));
await page.click('.night-btn[data-night="1"]');
await page.click('#nightPlayBtn');
await page.waitForTimeout(500);
const afterPlay = await page.evaluate(() => ({ state: window.__FNAF.game.state, night: window.__FNAF.game.night }));

await forcePlaying();
await page.waitForTimeout(300);
// Keyboard controls
await page.keyboard.press('q');
await page.keyboard.press('g');
await page.waitForTimeout(400);
const keys1 = await page.evaluate(() => ({ doors: { ...window.__FNAF.game.doors }, lights: { ...window.__FNAF.game.lights } }));
await page.keyboard.press('c');
await page.waitForTimeout(500);
const camKeyOpen = await page.evaluate(() => ({ state: window.__FNAF.game.state, camOpen: window.__FNAF.game.camOpen }));
await page.keyboard.press('Escape');
await page.waitForTimeout(400);
const escClosed = await page.evaluate(() => ({ state: window.__FNAF.game.state, camOpen: window.__FNAF.game.camOpen }));

// Cycle every channel via UI
await page.click('#camBtn');
await page.waitForTimeout(300);
const ids = [];
for (const id of ['1','2','3','4','5']) {
  await page.click(`[data-cam="${id}"]`);
  await page.waitForTimeout(150);
  ids.push(await page.evaluate(() => ({ cam: window.__FNAF.game.camId, header: document.querySelector('#camName').textContent, active: document.querySelector('.cam-map-btn.active')?.dataset.cam })));
}
await page.click('#camExit');
await page.waitForTimeout(300);

// Quit to menu from game over
await page.evaluate(() => { const g=window.__FNAF.game; g.deathReason='bonnie'; g.showGameOver(); });
await page.waitForTimeout(300);
await page.click('#quitBtn');
await page.waitForTimeout(400);
const menuBack = await page.evaluate(() => ({ state: window.__FNAF.game.state, menuHidden: document.querySelector('#menu').classList.contains('hidden') }));

console.log(JSON.stringify({ settings, howOpen, nightOpen, afterPlay, keys1, camKeyOpen, escClosed, ids, menuBack, errors }, null, 2));
await browser.close();

